import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

// The API reference sidebar is generated by TypeDoc (docusaurus-plugin-typedoc) on every build.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const generatedApiSidebar = require("./content/api/typedoc-sidebar.cjs");

// Each of its categories keyed by its path: TypeDoc gives the package and the `ui` namespace a
// "Functions" category each, and two items with one label collide as translation keys (the
// Spanish site's sidebar). The labels shown don't change.
type ApiItem = { type: string; label?: string; key?: string; items?: ApiItem[] };
const keyed = (items: ApiItem[], parent: string): ApiItem[] =>
  items.map((item) => {
    if (item.type !== "category" || !item.items) return item;
    const key = `${parent}/${item.label}`;
    return { ...item, key, items: keyed(item.items, key) };
  });
const apiSidebar = keyed(generatedApiSidebar, "api");

